/* ================= VIEWS: leadership, office, finance, assessment ================= */
const V={};
const COL=["#14213d","#f7c51e","#13b5d6","#ef7d6b","#7c6bd6","#3fb37f"];
function ph(title,sub,right=""){return `<div class="pagehead"><div><div class="sub">${sub||""}</div></div><span class="sp"></span>${right}</div>`}

/* ---------- finance computations ---------- */
function monthCollected(m){return S.payments.filter(p=>{const i=S.invoices.find(x=>x.no===p.inv);return i&&i.month===m}).reduce((s,p)=>s+p.amount,0)}
function monthInvoiced(m){return S.invoices.filter(i=>i.month===m).reduce((s,i)=>s+i.amount,0)}
function payroll(){return S.STAFF.reduce((s,x)=>s+x.salary,0)}
function monthExpenses(m){if(m==="2026-10")return payroll()+S.expenses.filter(e=>e[0].startsWith(m)).reduce((s,e)=>s+e[3],0);if(m==="2026-09")return payroll()+2318;return 0}
function finSeries(){const labs=S.history.map(h=>h[0]).concat(["Sep","Oct","Nov"]);
  const col=S.history.map(h=>h[1]).concat(["2026-09","2026-10","2026-11"].map(monthCollected));
  const inv=S.history.map(h=>h[2]).concat(["2026-09","2026-10","2026-11"].map(monthInvoiced));
  const exp=S.history.map(h=>h[3]).concat([monthExpenses("2026-09"),monthExpenses("2026-10"),null]);
  return {labs,col,inv,exp}}
function aging(){const t=new Date(DEMO_TODAY);const b={"Not yet due":0,"1–30 days":0,"31–60 days":0,"60+ days":0};
  S.invoices.filter(i=>i.status!=="paid").forEach(i=>{const d=(t-new Date(i.due))/864e5;b[d<=0?"Not yet due":d<=30?"1–30 days":d<=60?"31–60 days":"60+ days"]+=i.amount});return b}

/* ---------- PRINCIPAL DASHBOARD ---------- */
V.overview=()=>{
  const n=S.kids.length,cap=S.CLASSES.reduce((s,c)=>s+c.cap,0),ti=TODAY_I();
  const pres=S.kids.filter(k=>todayAtt(k)!=="A").length;
  const last30=S.days.slice(-30).map((d,i)=>Math.round(dayRate(S.days.length-30+i)*1000)/10);
  const termRate=avg(S.kids.map(k=>attRate(k)))*100;
  const oct=monthInvoiced("2026-10"),octC=monthCollected("2026-10"),nov=monthInvoiced("2026-11"),novC=monthCollected("2026-11");
  const fin=finSeries();const enq=S.admissions.filter(a=>a.stage!=="Enrolled").length;
  const blAvg=avg(S.kids.map(k=>avg(kidMarks(k,"BL"))));
  const staffT=S.STAFF.filter(s=>s.dept==="Teaching").length;
  const alerts=notifs();
  return ph("","Thursday 22 October 2026 · Term 1, week 9",`<span class="demo-flag">Demo data</span>`)+`
  <div class="kpis">
    <div class="kpi"><small>👧 Enrolment</small><b>${n}<span> / ${cap}</span></b><em class="up">${pct(n,cap)}% capacity · +${S.kids.filter(k=>k.newJoiner).length} this term</em></div>
    <div class="kpi"><small>✅ Present today</small><b>${pres}<span> / ${n}</span></b><em class="${pres/n>=.9?"up":"w"}">${pct(pres,n)}% · term avg ${termRate.toFixed(1)}%</em>${spark(last30.slice(-12),"#3fb37f")}</div>
    <div class="kpi"><small>💰 October collection</small><b>${pct(octC,oct)}%</b><em>${f0(octC)} of ${f0(oct)} OMR</em>${spark(fin.col.slice(-6,-1),"#f7c51e")}</div>
    <div class="kpi"><small>🧾 November billed</small><b>${f0(nov)}<span> OMR</span></b><em>${pct(novC,nov)}% already paid</em></div>
    <div class="kpi"><small>🎓 Baseline average</small><b>${blAvg.toFixed(0)}<span>%</span></b><em>Mid-term ${entryPctAll()}% entered</em></div>
    <div class="kpi"><small>📝 Open enquiries</small><b>${enq}</b><em class="up">${S.admissions.filter(a=>a.stage==="Enrolled").length} enrolled this month</em></div>
  </div>
  <div class="g g21">
    <div class="card"><h3>Attendance rate · last 30 school days<span class="x">target 92%</span></h3>${chart("line",{labels:S.days.slice(-30).map(fd),series:[{name:"Attendance",color:"#3fb37f",data:last30}],min:70,max:100,fmt:v=>Math.round(v),unit:"%",target:92,area:true},230)}</div>
    <div class="card"><h3>⚠️ Needs your attention</h3>${alerts.length?alerts.map(a=>`<div class="alert w"><span style="font-size:18px">${a[0]}</span><span style="flex:1"><b>${a[1]}</b>${esc(a[2])}</span><button class="btn sm light" onclick="go('${a[3]}')">Open</button></div>`).join(""):`<div class="list-empty">All clear ✨</div>`}</div>
  </div>
  <div class="g g2" style="margin-top:14px">
    <div class="card"><h3>Revenue vs expenses (OMR)<span class="x"><button class="btn sm light" onclick="go('finance')">Finance →</button></span></h3>${chart("bar",{labels:fin.labs,series:[{name:"Collected",color:"#14213d",data:fin.col},{name:"Expenses",color:"#ef7d6b",data:fin.exp.map(v=>v||0)}],unit:" OMR"},240)}<div class="legend"><span><i style="background:#14213d"></i>Fees collected</span><span><i style="background:#ef7d6b"></i>Expenses</span><span>November is month-to-date</span></div></div>
    <div class="card"><h3>Class occupancy & today's attendance</h3><div class="tbl"><table><thead><tr><th>Class</th><th>Enrolled</th><th>Present</th><th>Staff</th><th>Ratio</th></tr></thead><tbody>
      ${S.CLASSES.map(c=>{const ks=classKids(c.id),p=ks.filter(k=>todayAtt(k)!=="A").length,st=S.STAFF.filter(s=>s.cls===c.id).length,ok=p/st<=c.ratio;
      return `<tr><td><span class="mini"><span class="av sm" style="background:${c.bg}">${c.em}</span><span><b style="font-weight:600">${c.name}</b><small>${c.age}</small></span></span></td><td><div style="display:flex;gap:8px;align-items:center"><div class="prog"><i style="width:${pct(ks.length,c.cap)}%;background:${c.color}"></i></div>${ks.length}/${c.cap}</div></td><td>${p}</td><td>${st}</td><td><span class="st ${ok?"ok":"bad"}">1:${(p/st).toFixed(1)} ${ok?"✓":"over"}</span></td></tr>`}).join("")}
    </tbody></table></div></div>
  </div>
  <div class="g g3" style="margin-top:14px">
    <div class="card"><h3>Admissions funnel</h3>${chart("funnel",{data:funnelData()},210)}</div>
    <div class="card"><h3>Baseline by learning area</h3>${chart("hbar",{items:AREAS.map((a,i)=>({label:a,value:avg(S.kids.map(k=>kidMarks(k,"BL")[i])),color:COL[i%6]})),max:100,unit:"%"},210)}</div>
    <div class="card"><h3>Payment methods · this term</h3>${chart("donut",{data:methodData(),center:pct(S.payments.filter(p=>p.method==="Card").length,S.payments.length)+"%",sub:"paid by card"},210)}</div>
  </div>`};
function entryPctAll(){let n=0,t=0;S.kids.forEach(k=>kidMarks(k,"MT").forEach(v=>{t++;if(v!=null)n++}));return pct(n,t)}
function funnelData(){const st=["Enquiry","Tour booked","Applied","Offer sent","Enrolled"];const idx=s=>st.indexOf(s);const a=mergedAdmissions();
  return st.map((s,i)=>({label:s,value:a.filter(x=>idx(x.stage)>=i).length+[22,14,9,6,0][i],color:["#13b5d6","#2a9fc2","#7c6bd6","#f7a21e","#3fb37f"][i]}))}
function methodData(){const m={};S.payments.forEach(p=>m[p.method]=(m[p.method]||0)+1);return [["Card","#14213d"],["Bank transfer","#13b5d6"],["Cash","#f7c51e"]].map(([k,c])=>({label:k,value:m[k]||0,color:c}))}

/* ---------- ANALYTICS ---------- */
V.analytics=(p)=>{const tab=(p&&p.tab)||"att";
  const tabs=[["att","Attendance"],["acad","Academic"],["fin","Finance"],["adm","Admissions"],["ops","Operations"]];
  let body="";
  if(tab==="att"){
    const all=S.days.map((d,i)=>Math.round(dayRate(i)*1000)/10);
    const byCls=S.CLASSES.map(c=>({label:c.name,value:avg(classKids(c.id).map(k=>attRate(k)))*100,color:c.color}));
    const wd=[0,1,2,3,4].map(w=>{const idx=S.days.map((d,i)=>[d,i]).filter(x=>new Date(x[0]).getDay()===w).map(x=>x[1]);return avg(idx.map(i=>dayRate(i)))*100});
    const low=S.kids.map(k=>[k,attRate(k)]).filter(x=>x[1]<.88).sort((a,b)=>a[1]-b[1]);
    const weeks=[];for(let i=0;i<S.days.length;i+=5)weeks.push([i,Math.min(i+5,S.days.length)]);
    body=`<div class="g g21"><div class="card"><h3>Daily attendance · whole term</h3>${chart("line",{labels:S.days.map(fd),series:[{name:"Attendance",color:"#14213d",data:all}],min:60,max:100,fmt:v=>Math.round(v),unit:"%",target:92,area:true},250)}</div>
      <div class="card"><h3>By weekday</h3>${chart("bar",{labels:["Sun","Mon","Tue","Wed","Thu"],series:[{name:"Avg attendance",color:"#13b5d6",data:wd.map(v=>Math.round(v*10)/10)}],max:100,fmt:v=>Math.round(v),unit:"%"},250)}<div class="hint">Sundays are consistently the lowest-attendance day.</div></div></div>
      <div class="g g2" style="margin-top:14px"><div class="card"><h3>Term attendance by class</h3>${chart("hbar",{items:byCls,max:100,fmt:v=>v.toFixed(1),unit:"%"},180)}
       <h3 style="margin-top:14px">Weekly heatmap</h3><div style="overflow-x:auto"><table style="min-width:420px"><tr><th></th>${weeks.map((w,i)=>`<th style="text-align:center">W${i+1}</th>`).join("")}</tr>${S.CLASSES.map(c=>`<tr><td style="font-size:12px;font-weight:600">${c.name}</td>${weeks.map(w=>{const ks=classKids(c.id);let v=0,cnt=0;for(let i=w[0];i<w[1];i++){v+=dayRate(i,ks);cnt++}v=v/cnt;const a=Math.max(0,Math.min(1,(v-.75)/.25));return `<td style="padding:3px"><i data-tip="${c.name} · W${weeks.indexOf(w)+1}: ${(v*100).toFixed(0)}%" style="display:block;height:26px;border-radius:6px;background:rgba(31,157,104,${.15+a*.85})"></i></td>`}).join("")}</tr>`).join("")}</table></div></div>
      <div class="card"><h3>Below 88% attendance<span class="x">${low.length} children</span></h3><div class="tbl"><table><thead><tr><th>Child</th><th>Class</th><th class="r">Rate</th><th></th></tr></thead><tbody>${low.slice(0,10).map(([k,r])=>`<tr><td>${kidCell(k)}</td><td>${C(k.cls).name}</td><td class="r"><b>${(r*100).toFixed(0)}%</b></td><td><button class="btn sm light" onclick="contactParent('${k.id}','attendance')">Contact</button></td></tr>`).join("")}</tbody></table></div></div></div>`}
  if(tab==="acad"){
    const bandCnt={E:0,D:0,S:0,X:0};S.kids.forEach(k=>{const b=band(avg(kidMarks(k,"BL")));bandCnt[b[0]]++});
    const growth=S.CLASSES.map(c=>{const ks=classKids(c.id).filter(k=>kidMarks(k,"MT")[0]!=null);return[c,avg(ks.map(k=>avg(kidMarks(k,"BL")))),avg(ks.map(k=>avg(kidMarks(k,"MT"))))]});
    const support=S.kids.map(k=>[k,avg(kidMarks(k,"BL"))]).filter(x=>x[1]<58).sort((a,b)=>a[1]-b[1]);
    body=`<div class="card"><h3>Baseline average by learning area and class</h3>${chart("bar",{labels:AREAS.map(a=>a.split(" ")[0]),series:S.CLASSES.map(c=>({name:c.name,color:c.color,data:AREAS.map((a,i)=>Math.round(avg(classKids(c.id).map(k=>kidMarks(k,"BL")[i]))))})),max:100,unit:"%"},260)}<div class="legend">${S.CLASSES.map(c=>`<span><i style="background:${c.color}"></i>${c.name}</span>`).join("")}</div></div>
     <div class="g g3" style="margin-top:14px"><div class="card"><h3>Overall bands · baseline</h3>${chart("donut",{data:[["X","Exceeding","#2a6fdb"],["S","Secure","#3fb37f"],["D","Developing","#f7a21e"],["E","Emerging","#ef7d6b"]].map(b=>({label:b[1],value:bandCnt[b[0]],color:b[2]})),center:pct(bandCnt.S+bandCnt.X,S.kids.length)+"%",sub:"secure or above"},210)}</div>
      <div class="card"><h3>Growth: baseline → mid-term<span class="x">children with marks</span></h3>${growth.map(([c,a,b])=>`<div class="row"><span><b>${c.name}</b><small>${a?a.toFixed(0):"–"}% → ${b?b.toFixed(0):"–"}%</small></span><span class="st ${b-a>3?"ok":"info"}">${b?"+"+(b-a).toFixed(1)+" pts":"pending"}</span></div>`).join("")}</div>
      <div class="card"><h3>May need extra support<span class="x">${support.length}</span></h3>${support.slice(0,6).map(([k,v])=>`<div class="row">${kidCell(k,C(k.cls).name)}${bandChip(v)}</div>`).join("")||'<div class="list-empty">None</div>'}</div></div>`}
  if(tab==="fin"){const f=finSeries(),ag=aging();
    const byCls=S.CLASSES.map(c=>{const iv=S.invoices.filter(i=>i.month==="2026-10"&&K(i.kid).cls===c.id);return{label:c.name,value:pct(iv.filter(i=>i.status==="paid").reduce((s,i)=>s+i.amount,0),iv.reduce((s,i)=>s+i.amount,0)),color:c.color}});
    const cats={};S.expenses.forEach(e=>cats[e[1]]=(cats[e[1]]||0)+e[3]);cats.Salaries=payroll();
    body=`<div class="g g21"><div class="card"><h3>Invoiced vs collected (OMR)</h3>${chart("line",{labels:f.labs,series:[{name:"Invoiced",color:"#13b5d6",data:f.inv,dash:true},{name:"Collected",color:"#14213d",data:f.col}],unit:" OMR",area:false},250)}<div class="legend"><span><i style="background:#13b5d6"></i>Invoiced</span><span><i style="background:#14213d"></i>Collected</span></div></div>
     <div class="card"><h3>Outstanding by age (OMR)</h3>${chart("bar",{labels:Object.keys(ag).map(x=>x.replace(" days","d")),series:[{name:"Outstanding",color:"#ef7d6b",data:Object.values(ag)}],unit:" OMR"},250)}</div></div>
     <div class="g g2" style="margin-top:14px"><div class="card"><h3>October collection rate by class</h3>${chart("hbar",{items:byCls,max:100,unit:"%"},180)}</div>
     <div class="card"><h3>October costs by category (OMR)</h3>${chart("donut",{data:Object.entries(cats).sort((a,b)=>b[1]-a[1]).map(([k,v],i)=>({label:k,value:Math.round(v),color:COL.concat(["#9aa3b5","#c9a227","#5bc0de"])[i]})),center:f0(Object.values(cats).reduce((s,v)=>s+v,0)),sub:"OMR total",fmt:f0},230)}</div></div>`}
  if(tab==="adm"){const a=mergedAdmissions();const src={};a.forEach(x=>src[x.src]=(src[x.src]||0)+1);
    const wk=[3,5,4,6,7,5,8,a.filter(x=>x.date>="2026-10-16").length];
    body=`<div class="kpis"><div class="kpi"><small>Enquiries this term</small><b>${a.length+22}</b><em class="up">+18% vs last term</em></div><div class="kpi"><small>Enquiry → enrolled</small><b>${pct(funnelData()[4].value,funnelData()[0].value)}%</b><em>conversion</em></div><div class="kpi"><small>Avg days to enrol</small><b>16</b><em>from first enquiry</em></div><div class="kpi"><small>Spaces left</small><b>${S.CLASSES.reduce((s,c)=>s+c.cap,0)-S.kids.length}</b><em>across all classes</em></div></div>
     <div class="g g3"><div class="card"><h3>Funnel</h3>${chart("funnel",{data:funnelData()},230)}</div><div class="card"><h3>Lead sources</h3>${chart("donut",{data:Object.entries(src).map(([k,v],i)=>({label:k,value:v,color:COL[i%6]})),center:a.length,sub:"active leads"},230)}</div>
     <div class="card"><h3>New enquiries per week</h3>${chart("bar",{labels:["W2","W3","W4","W5","W6","W7","W8","W9"],series:[{name:"Enquiries",color:"#7c6bd6",data:wk}]},230)}</div></div>`}
  if(tab==="ops"){const it={};S.incidents.forEach(i=>it[i.type]=(it[i.type]||0)+1);
    body=`<div class="g g3"><div class="card"><h3>Staff : child ratio today</h3>${S.CLASSES.map(c=>{const p=classKids(c.id).filter(k=>todayAtt(k)!=="A").length,st=S.STAFF.filter(s=>s.cls===c.id).length;return `<div class="row"><span><b>${c.name}</b><small>Required 1:${c.ratio}</small></span><span class="st ${p/st<=c.ratio?"ok":"bad"}">1:${(p/st).toFixed(1)}</span></div>`}).join("")}</div>
     <div class="card"><h3>Incidents by type · this term</h3>${chart("hbar",{items:Object.entries(it).map(([k,v],i)=>({label:k,value:v,color:COL[(i+2)%6]}))},170)}</div>
     <div class="card"><h3>Parent engagement</h3><div class="row"><span>Notice read rate</span><b>${pct(S.news.reduce((s,n)=>s+n.reads,0),S.news.reduce((s,n)=>s+(n.to==="All"?62:classKids(n.to).length),0))}%</b></div><div class="row"><span>Parents paying online</span><b>${pct(S.payments.filter(p=>p.method==="Card").length,S.payments.length)}%</b></div><div class="row"><span>Messages answered &lt; 1 hour</span><b>94%</b></div><div class="row"><span>Active parent accounts</span><b>58 / 62</b></div></div></div>
     <div class="card" style="margin-top:14px"><h3>Inventory below minimum</h3>${S.inventory.filter(i=>i.qty<i.min).map(i=>`<div class="alert w"><span>📦</span><span style="flex:1"><b>${i.item}</b>${i.qty} ${i.unit} left · minimum ${i.min}</span></div>`).join("")||'<div class="list-empty">All stocked</div>'}</div>`}
  return `<div class="toolbar"><div class="seg">${tabs.map(t=>`<button class="${t[0]===tab?"on":""}" onclick="go('analytics',{tab:'${t[0]}'})">${t[1]}</button>`).join("")}</div><span class="sp"></span><span class="demo-flag">Demo data</span></div>`+body};

/* ---------- ADMIN TODAY ---------- */
V.adminHome=()=>{const ti=TODAY_I(),k=S.kids;
  const pres=k.filter(x=>todayAtt(x)==="P").length,late=k.filter(x=>todayAtt(x)==="L").length,abs=k.filter(x=>todayAtt(x)==="A");
  const pend=S.leave.filter(l=>l.status==="pending"),enq=mergedAdmissions().filter(a=>a.stage==="Enquiry"||a.stage==="Tour booked");
  return ph("","Thursday 22 October 2026",`<button class="btn sm" onclick="go('kiosk')">📲 Open QR check-in</button><button class="btn sm navy" onclick="composeNotice()">📣 Send notice</button>`)+`
  <div class="kpis"><div class="kpi"><small>Present</small><b>${pres+late}</b><em>${late} arrived late</em></div><div class="kpi"><small>Absent</small><b>${abs.length}</b><em class="w">${abs.filter(a=>!S.leave.some(l=>l.kid===a.id)).length} without notice</em></div><div class="kpi"><small>Absence requests</small><b>${pend.length}</b><em>awaiting approval</em></div><div class="kpi"><small>Visits & enquiries</small><b>${enq.length}</b><em>to follow up</em></div></div>
  <div class="g g2"><div class="card"><h3>🚫 Absent without notice<span class="x"><button class="btn sm light" onclick="bulkAbsentMsg()">WhatsApp all</button></span></h3>${abs.slice(0,8).map(a=>`<div class="row">${kidCell(a,C(a.cls).name+" · "+esc(a.mother))}<button class="btn sm light" onclick="contactParent('${a.id}','absence')">Contact</button></div>`).join("")||'<div class="list-empty">Everyone is in 🎉</div>'}</div>
   <div class="stack"><div class="card"><h3>🗓️ Absence requests</h3>${pend.map(leaveRow).join("")||'<div class="list-empty">None pending</div>'}</div>
   <div class="card"><h3>📝 Upcoming visits & new enquiries<span class="x"><button class="btn sm light" onclick="go('admissions')">Pipeline →</button></span></h3>${enq.slice(0,5).map(a=>`<div class="row"><span><b>${esc(a.child)}</b><small>${esc(a.prog)} · ${esc(a.parent)}${a.tour?" · tour "+esc(a.tour):""}</small></span><span class="st ${a.stage==="Enquiry"?"gold":"info"}">${a.src==="Website"&&a.web?"🌐 ":""}${a.stage}</span></div>`).join("")}</div></div></div>
  <div class="g g2" style="margin-top:14px"><div class="card"><h3>📅 Coming up</h3>${upcoming(5).map(e=>`<div class="row"><span><b>${esc(e.title)}</b><small>${fdl(e.date)} · ${e.cls==="All"?"Whole nursery":C(e.cls).name}</small></span><span class="st info">${e.type}</span></div>`).join("")}</div>
   <div class="card"><h3>🛂 Staff documents expiring</h3>${S.STAFF.filter(s=>(s.visa&&s.visa<"2027-01-31")||(s.firstAid&&s.firstAid<"2027-01-31")).map(s=>`<div class="row"><span><b>${s.name}</b><small>${s.role}</small></span><span class="st ${((s.visa||"9")<"2026-11-30")?"bad":"w"}">${s.visa&&s.visa<"2027-01-31"?"Visa "+fd(s.visa):"First aid "+fd(s.firstAid)}</span></div>`).join("")}</div></div>`};
function upcoming(n){return S.events.filter(e=>e.date>=DEMO_TODAY).sort((a,b)=>a.date.localeCompare(b.date)).slice(0,n)}
function contactParent(id,why){const k=K(id);modal(mh("Contact "+esc(k.mother),k.name+" · "+C(k.cls).name)+`<div class="f"><label>Channel</label><select id="cch"><option>WhatsApp</option><option>SMS</option><option>Call</option><option>Email</option></select></div><div class="f"><label>Message</label><textarea id="cmsg">${why==="absence"?`Good morning, ${k.first} hasn't checked in today. Is everything okay? – TwinkleStar`:why==="attendance"?`Dear ${k.mother.split(" ")[0]}, we noticed ${k.first}'s attendance is ${Math.round(attRate(k)*100)}% this term. Could we have a quick chat? – TwinkleStar`:"Hello from TwinkleStar!"}</textarea></div><div class="row"><span>📞 ${k.phone}</span><span>✉️ ${k.email}</span></div><button class="btn full" onclick="logComm($('#cch').value,'${esc(k.mother)}',$('#cmsg').value);closeModal();toast('Sent to ${esc(k.mother)}')">Send</button>`)}
function logComm(ch,to,x){S.commsLog.unshift({t:DEMO_TODAY+" "+nowT(),ch,to,x});save()}
function bulkAbsentMsg(){const a=S.kids.filter(k=>todayAtt(k)==="A"&&!S.leave.some(l=>l.kid===k.id));a.forEach(k=>logComm("WhatsApp",k.mother,`${k.first} hasn't checked in today.`));toast(`WhatsApp sent to ${a.length} parents`)}
function leaveRow(l){const k=K(l.kid);return `<div class="row">${kidCell(k,`${fd(l.from)}${l.to!==l.from?" – "+fd(l.to):""} · ${esc(l.reason)}`)}${l.status==="pending"?`<span style="display:flex;gap:6px"><button class="btn sm ok" onclick="setLeave('${l.id}','approved')">Approve</button><button class="btn sm danger" onclick="setLeave('${l.id}','declined')">Decline</button></span>`:`<span class="st ${l.status==="approved"?"ok":"bad"}">${l.status}</span>`}</div>`}
function setLeave(id,s){const l=S.leave.find(x=>x.id===id);l.status=s;logComm("WhatsApp",K(l.kid).mother,`Absence request for ${K(l.kid).first} ${s}.`);toast(`Request ${s} · parent notified`);go(view,param)}
V.leave=()=>{const list=S.leave.filter(l=>me.role!=="teacher"||K(l.kid).cls===me.cls);return ph("","Parents report absences from the portal. Approving notifies the parent and updates the register.")+`<div class="card">${list.map(leaveRow).join("")||'<div class="list-empty">No requests</div>'}</div>`};

/* ---------- QR KIOSK ---------- */
V.kiosk=()=>{const notIn=S.kids.filter(k=>todayAtt(k)==="A"&&!S.leave.some(l=>l.kid===k.id&&l.status==="approved"));const recent=S.kids.filter(k=>S.checkin[k.id]).sort((a,b)=>S.checkin[b.id].padStart(5,"0").localeCompare(S.checkin[a.id].padStart(5,"0"))).slice(0,8);
  return ph("","Parents show the pick-up pass QR from their app at the entrance. Check-in is recorded and the parent is notified instantly.")+`
  <div class="g g2"><div class="card" style="text-align:center;padding:28px"><div style="width:220px;height:220px;margin:0 auto;border-radius:20px;background:#0d1529;display:grid;place-items:center;position:relative;overflow:hidden"><div style="position:absolute;left:10%;right:10%;height:3px;background:#f7c51e;box-shadow:0 0 18px #f7c51e;animation:scan 2s ease-in-out infinite"></div><span style="font-size:60px">📲</span></div>
    <style>@keyframes scan{0%,100%{top:15%}50%{top:85%}}</style><h3 style="margin:16px 0 4px;justify-content:center">Ready to scan</h3><div class="hint">Demo: simulate a parent scanning their pass</div>
    <div class="f" style="max-width:320px;margin:14px auto 10px"><select id="kk">${notIn.map(k=>`<option value="${k.id}">${esc(k.name)} · ${C(k.cls).name}</option>`).join("")}</select></div>
    <button class="btn" onclick="kioskScan()" ${notIn.length?"":"disabled"}>✅ Simulate scan</button></div>
   <div class="card"><h3>Recent check-ins</h3>${recent.map(k=>`<div class="row">${kidCell(k,C(k.cls).name)}<span class="st ok">${S.checkin[k.id]}</span></div>`).join("")}</div></div>`};
function kioskScan(){const k=K($("#kk").value);if(!k)return;const i=TODAY_I();S.att[k.id]=S.att[k.id].slice(0,i)+"P";S.checkin[k.id]=nowT().replace(/^0/,"");S.daily[k.id]={entries:[[nowT(),"🚗","Checked in at the entrance"]],mood:-1,note:""};logComm("WhatsApp",k.mother,`${k.first} checked in at ${S.checkin[k.id]} ✅`);toast(`${k.first} checked in · ${k.mother.split(" ")[0]} notified on WhatsApp`);go("kiosk")}

/* ---------- ATTENDANCE (admin/principal/teacher) ---------- */
V.attendance=(p)=>{p=p||{};const mode=p.mode||"today",cls=me.role==="teacher"?me.cls:(p.cls||"");
  const list=S.kids.filter(k=>!cls||k.cls===cls);const ti=TODAY_I();
  const tb=`<div class="toolbar"><div class="seg"><button class="${mode==="today"?"on":""}" onclick="go('attendance',{cls:'${cls}',mode:'today'})">Today's register</button><button class="${mode==="term"?"on":""}" onclick="go('attendance',{cls:'${cls}',mode:'term'})">Term summary</button></div>${me.role==="teacher"?"":clsFilter("ac",cls)}<span class="sp"></span>${mode==="today"?`<button class="btn sm light" onclick="markAll('${cls}')">Mark unmarked present</button>`:`<button class="btn sm light" onclick="exportAtt('${cls}')">⬇ Export CSV</button>`}</div>`;
  if(mode==="today"){const pres=list.filter(k=>todayAtt(k)!=="A").length;
    return tb+`<div class="kpis"><div class="kpi"><small>Present</small><b>${pres}<span> / ${list.length}</span></b><em>${pct(pres,list.length)}%</em></div><div class="kpi"><small>Late</small><b>${list.filter(k=>todayAtt(k)==="L").length}</b><em>after 8:15</em></div><div class="kpi"><small>Absent</small><b>${list.filter(k=>todayAtt(k)==="A").length}</b><em>${S.leave.filter(l=>l.from<=DEMO_TODAY&&l.to>=DEMO_TODAY).length} with notice</em></div></div>
    <div class="card"><div class="tbl"><table><thead><tr><th>Child</th><th>Class</th><th>Check-in</th><th>Status</th><th class="r">Term</th></tr></thead><tbody>${list.map(k=>{const a=todayAtt(k);return `<tr><td>${kidCell(k,k.allergy!=="None"?"⚠️ "+k.allergy:"")}</td><td>${C(k.cls).name}</td><td class="num">${a!=="A"?S.checkin[k.id]||"—":"—"}</td><td><div class="tog"><button class="p ${a==="P"?"on":""}" onclick="setAtt('${k.id}','P')">Present</button><button class="l ${a==="L"?"on":""}" onclick="setAtt('${k.id}','L')">Late</button><button class="a ${a==="A"?"on":""}" onclick="setAtt('${k.id}','A')">Absent</button></div></td><td class="r num">${Math.round(attRate(k)*100)}%</td></tr>`}).join("")}</tbody></table></div></div>`}
  const rows=list.map(k=>{const s=S.att[k.id];return[k,[...s].filter(c=>c==="P").length,[...s].filter(c=>c==="L").length,[...s].filter(c=>c==="A").length,attRate(k)]}).sort((a,b)=>a[4]-b[4]);
  return tb+`<div class="card"><h3>${S.days.length} school days · 30 Aug – 22 Oct<span class="x">sorted lowest first</span></h3><div class="tbl"><table><thead><tr><th>Child</th><th>Class</th><th class="r">Present</th><th class="r">Late</th><th class="r">Absent</th><th style="min-width:160px">Rate</th></tr></thead><tbody>${rows.map(r=>`<tr><td>${kidCell(r[0])}</td><td>${C(r[0].cls).name}</td><td class="r">${r[1]}</td><td class="r">${r[2]}</td><td class="r">${r[3]}</td><td><div style="display:flex;gap:8px;align-items:center"><div class="prog"><i style="width:${r[4]*100}%;background:${r[4]<.85?"#d64545":r[4]<.92?"#d98500":"#1f9d68"}"></i></div><b class="num">${(r[4]*100).toFixed(0)}%</b></div></td></tr>`).join("")}</tbody></table></div></div>`};
function setAtt(id,s){const k=K(id),i=TODAY_I(),was=todayAtt(k);S.att[id]=S.att[id].slice(0,i)+s;if(s!=="A"&&!S.checkin[id])S.checkin[id]=nowT().replace(/^0/,"");if(s!=="A"&&was==="A"){logComm("WhatsApp",k.mother,`${k.first} checked in ✅`);toast(`${k.mother.split(" ")[0]} notified: ${k.first} checked in`)}go("attendance",param)}
function markAll(cls){let n=0;S.kids.filter(k=>(!cls||k.cls===cls)&&todayAtt(k)==="A"&&!S.leave.some(l=>l.kid===k.id)).forEach(k=>{if(n<3){S.att[k.id]=S.att[k.id].slice(0,-1)+"P";S.checkin[k.id]=nowT().replace(/^0/,"");n++}});toast(n?`${n} children marked present`:"Nothing to mark");go("attendance",param)}
function exportAtt(cls){csv("attendance-term1.csv",[["Student","Class",...S.days]].concat(S.kids.filter(k=>!cls||k.cls===cls).map(k=>[k.name,C(k.cls).name,...S.att[k.id]])))}

/* ---------- STUDENTS ---------- */
V.children=(p)=>{p=p||{};const q=(p.q||"").toLowerCase(),cls=p.cls||"";const fin=["accounts","principal","admin"].includes(me.role);
  const list=S.kids.filter(k=>(!cls||k.cls===cls)&&(!q||(k.name+" "+k.mother+" "+k.father+" "+k.id).toLowerCase().includes(q)));
  return `<div class="toolbar"><input type="search" placeholder="Search name, parent or ID…" value="${esc(p.q||"")}" onchange="go('children',{cls:'${cls}',q:this.value})">${clsFilter("cf",cls)}<span class="sp"></span>${me.role!=="accounts"?`<button class="btn sm navy" onclick="addStudent()">+ Add student</button>`:""}<button class="btn sm light" onclick="exportKids()">⬇ CSV</button></div>
  <div class="card"><h3>${list.length} students</h3><div class="tbl"><table><thead><tr><th>Student</th><th>Class</th><th>Age</th><th>Parent</th><th>Allergies</th><th class="r">Attendance</th>${fin?"<th>Fees</th>":""}<th>Docs</th></tr></thead><tbody>
  ${list.map(k=>{const due=kidInvoices(k).filter(i=>i.status!=="paid");return `<tr class="click" onclick="kidProfile('${k.id}')"><td>${kidCell(k,k.id)}</td><td>${C(k.cls).name}</td><td>${age(k)}</td><td>${esc(k.mother)}<small style="display:block;color:var(--muted)">${k.phone}</small></td><td>${k.allergy==="None"?"—":`<span class="st bad">${k.allergy}</span>`}</td><td class="r num">${Math.round(attRate(k)*100)}%</td>${fin?`<td>${due.some(i=>i.status==="overdue")?'<span class="st bad">Overdue</span>':due.length?'<span class="st w">Due</span>':'<span class="st ok">Paid</span>'}</td>`:""}<td>${k.vacc==="expired"?'<span class="st bad">Vaccination</span>':k.consent?'<span class="st ok">Complete</span>':'<span class="st w">Consent</span>'}</td></tr>`}).join("")}</tbody></table></div></div>`};
function exportKids(){csv("students.csv",[["ID","Name","Class","DOB","Gender","Nationality","Mother","Father","Phone","Email","Allergy","Blood","Attendance %"]].concat(S.kids.map(k=>[k.id,k.name,C(k.cls).name,k.dob,k.gender,k.nationality,k.mother,k.father,k.phone,k.email,k.allergy,k.blood,Math.round(attRate(k)*100)])))}
function kidProfile(id){const k=K(id),c=C(k.cls),bl=kidMarks(k,"BL"),mt=kidMarks(k,"MT"),fin=["accounts","principal","admin"].includes(me.role);
  const oct=S.days.map((d,i)=>[d,S.att[k.id][i]]).filter(x=>x[0].startsWith("2026-10"));
  drawer(`<div class="mh"><div class="mini">${kidAv(k,"lg")}<span><h3 style="font-size:19px">${esc(k.name)}</h3><small style="font-size:13px">${k.id} · ${c.name} · ${age(k)}</small></span></div><button class="x" onclick="closeModal()">×</button></div>
  <div class="kpis"><div class="kpi"><small>Attendance</small><b>${Math.round(attRate(k)*100)}%</b></div><div class="kpi"><small>Baseline avg</small><b>${Math.round(avg(bl))}%</b></div></div>
  <div class="card"><h3>👪 Family & pick-up</h3><div class="row"><span>Mother<small>${esc(k.mother)}</small></span><span>${k.phone}</span></div><div class="row"><span>Father<small>${esc(k.father)}</small></span><span>${k.email}</span></div>${k.pickup.map(p=>`<div class="row"><span>${esc(p[0])}</span><span class="st ok">${p[1]} · approved</span></div>`).join("")}</div>
  <div class="card"><h3>🩺 Health</h3><div class="row"><span>Allergies</span><b>${k.allergy}</b></div><div class="row"><span>Blood group</span><b>${k.blood}</b></div><div class="row"><span>Vaccination card</span><span class="st ${k.vacc==="valid"?"ok":"bad"}">${k.vacc}</span></div><div class="row"><span>Photo consent</span><span class="st ${k.consent?"ok":"w"}">${k.consent?"Signed":"Missing"}</span></div></div>
  <div class="card"><h3>🎓 Assessments</h3>${AREAS.map((a,i)=>`<div class="row"><span>${AREA_E[i]} ${a}</span><span style="display:flex;gap:6px;align-items:center"><span class="num">${bl[i]}%${mt[i]!=null?" → "+mt[i]+"%":""}</span>${bandChip(mt[i]!=null?mt[i]:bl[i])}</span></div>`).join("")}<button class="btn sm light" style="margin-top:10px" onclick="reportCard('${k.id}','BL')">📄 Baseline report card</button></div>
  <div class="card"><h3>✅ October attendance</h3>${calMonth(k,"2026-10")}</div>
  ${fin?`<div class="card"><h3>💳 Fees</h3>${kidInvoices(k).map(i=>`<div class="row"><span>${i.item}<small>${i.no}</small></span><span style="text-align:end">${f3(i.amount)}<br>${invStatus(i)}</span></div>`).join("")}</div>`:""}`)}

function addStudent(){modal(mh("Add student","Creates the profile and a parent portal account")+`<div class="f2"><div class="f"><label>First name</label><input id="nf" value="Tala"></div><div class="f"><label>Family name</label><input id="nl" value="Al-Amri"></div></div><div class="f2"><div class="f"><label>Class</label><select id="nc">${S.CLASSES.map(c=>`<option value="${c.id}">${c.name}</option>`).join("")}</select></div><div class="f"><label>Date of birth</label><input id="nd" type="date" value="2026-02-10"></div></div><div class="f2"><div class="f"><label>Mother</label><input id="nm" value="Shamsa Al-Amri"></div><div class="f"><label>Mobile</label><input id="np" value="+968 9xxx 2205"></div></div><button class="btn full" onclick="saveStudent()">Create student</button>`)}
function saveStudent(){const id="K"+String(S.kids.length+1).padStart(3,"0"),cls=$("#nc").value;const k={id,first:$("#nf").value,last:$("#nl").value,name:$("#nf").value+" "+$("#nl").value,gender:"F",cls,dob:$("#nd").value,months:8,mother:$("#nm").value,father:"—",phone:$("#np").value,email:"",allergy:"None",blood:"—",joined:DEMO_TODAY,newJoiner:true,attBase:.95,ability:.6,discount:0,pickup:[[$("#nm").value,"Mother"]],nationality:"Omani",vacc:"valid",consent:true};
  S.kids.push(k);S.att[id]="P".repeat(S.days.length);S.checkin[id]="8:00";S.marks.BL[id]=AREAS.map(()=>60);S.marks.MT[id]=AREAS.map(()=>null);S.comments[id]="";S.daily[id]={entries:[],mood:-1,note:""};
  S.invoices.push({no:"INV-"+(2000+S.invoices.length),kid:id,month:"2026-11",item:"Registration fee + Tuition – November",lines:[["Registration fee",50],["Tuition – November",C(cls).fee]],amount:50+C(cls).fee,issued:DEMO_TODAY,due:"2026-11-01",status:"due"});
  closeModal();toast(`${k.name} added · invoice raised · parent invite sent by WhatsApp`);go("children")}

/* ---------- ADMISSIONS ---------- */
const STAGES=["Enquiry","Tour booked","Applied","Offer sent","Enrolled"];
function mergedAdmissions(){let web=[];try{web=JSON.parse(localStorage.getItem("ts_enquiries")||"[]")}catch(e){}
  web.forEach(w=>{const id="W"+w.at;if(!S.admissions.some(a=>a.id===id)){const m=w.dob?Math.max(0,Math.round((new Date(DEMO_TODAY)-new Date(w.dob))/2.63e9)):null;
    S.admissions.unshift({id,child:w.child,age:m==null?"—":m<12?m+"m":Math.floor(m/12)+"y "+(m%12)+"m",prog:(w.prog||"").split(" (")[0],parent:w.parent,phone:w.phone,src:"Website",stage:w.type==="tour"&&w.date?"Tour booked":"Enquiry",date:w.at.slice(0,10),start:w.start||"—",tour:w.type==="tour"&&w.date?w.date+" "+(w.time||""):null,web:true,msg:w.msg})}});
  return S.admissions}
V.admissions=()=>{const a=mergedAdmissions();const web=a.filter(x=>x.web).length;
  return ph("","Every enquiry from the website, WhatsApp and walk-ins in one pipeline.",`<button class="btn sm navy" onclick="newEnquiry()">+ New enquiry</button>`)+
  (web?`<div class="alert info"><span>🌐</span><span><b>${web} enquiry${web>1?"ies":""} received from the website</b>Highlighted below. They arrive here automatically.</span></div>`:`<div class="alert info"><span>🌐</span><span><b>Website enquiries land here automatically.</b>Try it: submit the form on the website, then come back.</span></div>`)+
  `<div class="kanban">${STAGES.map((s,si)=>{const items=a.filter(x=>x.stage===s);return `<div class="col"><h4><span>${s}</span><span class="st mute">${items.length}</span></h4>${items.map(x=>`<div class="kc ${x.web?"new":""}"><b>${esc(x.child)}</b><small>${esc(x.age)} · ${esc(x.prog)}</small><small>👤 ${esc(x.parent)} · ${esc(x.phone)}</small><small>${x.web?"🌐 ":""}${esc(x.src)} · ${fd(x.date)}${x.tour?" · 📅 "+esc(x.tour):""}</small>${x.msg?`<small style="margin-top:4px">“${esc(x.msg)}”</small>`:""}<div class="acts">${si<4?`<button class="btn sm" onclick="advance('${x.id}')">${["Book tour","Mark applied","Send offer","Enrol ✓"][si]}</button>`:'<span class="st ok">Enrolled</span>'}<a class="btn sm light" target="_blank" rel="noopener" href="https://wa.me/${String(x.phone).replace(/\D/g,"")}">WhatsApp</a></div></div>`).join("")||'<div class="list-empty">—</div>'}</div>`}).join("")}</div>`};
function advance(id){const x=S.admissions.find(a=>a.id===id);const i=STAGES.indexOf(x.stage);x.stage=STAGES[i+1];if(x.stage==="Tour booked"&&!x.tour)x.tour="2026-10-26 9:30";
  const msg={"Tour booked":"Tour booked · confirmation sent on WhatsApp","Applied":"Application recorded · document checklist sent","Offer sent":"Offer sent with registration-fee payment link","Enrolled":"Enrolled 🎉 · welcome pack & portal invite sent"}[x.stage];logComm("WhatsApp",x.parent,msg);toast(msg);go("admissions")}
function newEnquiry(){modal(mh("New enquiry")+`<div class="f2"><div class="f"><label>Child</label><input id="ec"></div><div class="f"><label>Age</label><input id="ea" placeholder="e.g. 2y 3m"></div></div><div class="f2"><div class="f"><label>Parent</label><input id="ep"></div><div class="f"><label>Phone</label><input id="eph"></div></div><div class="f2"><div class="f"><label>Programme</label><select id="eg">${S.CLASSES.map(c=>`<option>${c.name}</option>`).join("")}</select></div><div class="f"><label>Source</label><select id="es"><option>Walk-in</option><option>WhatsApp</option><option>Instagram</option><option>Referral</option><option>Phone</option></select></div></div><button class="btn full" onclick="S.admissions.unshift({id:'AQ'+Date.now(),child:$('#ec').value||'New child',age:$('#ea').value||'—',prog:$('#eg').value,parent:$('#ep').value||'—',phone:$('#eph').value||'—',src:$('#es').value,stage:'Enquiry',date:DEMO_TODAY,start:'—'});closeModal();go('admissions')">Add to pipeline</button>`)}

/* ---------- INCIDENTS ---------- */
V.incidents=()=>{const list=S.incidents.filter(i=>me.role!=="teacher"||K(i.kid).cls===me.cls);
  return ph("","Accidents, illness, medication and allergy events, each acknowledged by the parent in the app.",`<button class="btn sm navy" onclick="logIncident()">+ Log incident</button>`)+`<div class="card"><div class="tbl"><table><thead><tr><th>When</th><th>Child</th><th>Type</th><th>Details</th><th>Recorded by</th><th>Parent</th></tr></thead><tbody>${list.map(i=>`<tr><td class="num">${fd(i.date)} ${i.date.slice(11)}</td><td>${kidCell(K(i.kid),C(K(i.kid).cls).name)}</td><td><span class="st ${i.type==="Minor injury"?"w":i.type==="Illness"?"bad":"info"}">${i.type}</span></td><td style="max-width:320px">${esc(i.detail)}</td><td>${esc(i.by)}</td><td>${i.ack?'<span class="st ok">Acknowledged</span>':'<span class="st w">Awaiting</span>'}</td></tr>`).join("")}</tbody></table></div></div>`};
function logIncident(){const ks=me.role==="teacher"?classKids(me.cls):S.kids;modal(mh("Log incident","The parent and principal are notified")+`<div class="f"><label>Child</label><select id="ik">${ks.map(k=>`<option value="${k.id}">${esc(k.name)}</option>`).join("")}</select></div><div class="f"><label>Type</label><select id="it"><option>Minor injury</option><option>Illness</option><option>Medication</option><option>Allergy check</option><option>Behaviour</option></select></div><div class="f"><label>What happened & action taken</label><textarea id="id">Small scratch on hand during outdoor play. Cleaned and plaster applied.</textarea></div><button class="btn full" onclick="S.incidents.unshift({id:'IN'+Date.now(),date:DEMO_TODAY+' '+nowT(),kid:$('#ik').value,type:$('#it').value,detail:$('#id').value,by:me.name,ack:false});logComm('App',K($('#ik').value).mother,'Incident report: '+$('#it').value);closeModal();toast('Logged · parent & principal notified');go('incidents')">Save & notify</button>`)}

/* ---------- STAFF & HR ---------- */
V.staff=()=>{const exp=S.STAFF.filter(s=>(s.visa&&s.visa<"2027-01-31")||(s.firstAid&&s.firstAid<"2027-01-31"));
  return ph("","Profiles, documents and ratios",`<button class="btn sm navy" onclick="toast('Demo: staff onboarding form')">+ Add staff</button>`)+`<div class="kpis"><div class="kpi"><small>Total staff</small><b>${S.STAFF.length}</b><em>${S.STAFF.filter(s=>s.dept==="Teaching").length} in classrooms</em></div><div class="kpi"><small>Children per classroom adult</small><b>1:${(S.kids.length/S.STAFF.filter(s=>s.dept==="Teaching").length).toFixed(1)}</b><em class="up">within policy</em></div><div class="kpi"><small>Documents expiring ≤ 3 months</small><b>${exp.length}</b><em class="w">renew in time</em></div><div class="kpi"><small>Monthly payroll</small><b>${f0(payroll())}<span> OMR</span></b><em>${S.payrollRun["2026-10"]?"October paid":"October pending"}</em></div></div>
  <div class="card"><div class="tbl"><table><thead><tr><th>Name</th><th>Role</th><th>Department</th><th>Joined</th><th>Visa</th><th>First aid</th><th>Phone</th></tr></thead><tbody>${S.STAFF.map(s=>{const chip=d=>!d?'<span class="st mute">n/a</span>':`<span class="st ${d<"2026-12-01"?"bad":d<"2027-02-01"?"w":"ok"}">${fd(d)}</span>`;return `<tr><td><span class="mini"><span class="av sm n">${ini(s.name)}</span><b style="font-weight:600">${s.name}</b></span></td><td>${s.role}</td><td>${s.dept}</td><td>${fd(s.join)}</td><td>${chip(s.visa)}</td><td>${chip(s.firstAid)}</td><td>${s.phone}</td></tr>`}).join("")}</tbody></table></div></div>`};

/* ---------- EVENTS & NOTICES ---------- */
function calendarGrid(month,events){const d0=new Date(month+"-01T00:00:00"),days=new Date(d0.getFullYear(),d0.getMonth()+1,0).getDate();let h=["Sun","Mon","Tue","Wed","Thu","Fri","Sat"].map(x=>`<div class="h">${x}</div>`).join("");
  for(let i=0;i<d0.getDay();i++)h+="<div></div>";for(let d=1;d<=days;d++){const ds=month+"-"+String(d).padStart(2,"0"),ev=events.filter(e=>e.date===ds),wd=new Date(ds).getDay();
    h+=`<div class="d ${ev.length?"E":""} ${ds===DEMO_TODAY?"T":""}" style="${wd>4?"opacity:.45":""}" ${ev.length?`data-tip="${esc(ev.map(e=>e.title).join(" · "))}"`:""}>${d}</div>`}return `<div class="cal" style="grid-template-columns:repeat(7,1fr)">${h}</div>`}
V.events=(p)=>{const m=(p&&p.m)||"2026-10";const scope=me.role==="parent"?["All",...parentKids().map(k=>k.cls)]:me.role==="teacher"?["All",me.cls]:null;
  const ev=S.events.filter(e=>!scope||scope.includes(e.cls)),nw=S.news.filter(n=>!scope||scope.includes(n.to));const can=["admin","principal","teacher"].includes(me.role);
  return `<div class="g g2"><div class="card"><h3>📅 ${monthName(m+"-")} 2026<span class="x"><button class="btn sm light" onclick="go('events',{m:'${m==="2026-10"?"2026-09":"2026-10"}'})">‹</button><button class="btn sm light" onclick="go('events',{m:'${m==="2026-12"?"2026-12":m==="2026-09"?"2026-10":m==="2026-10"?"2026-11":"2026-12"}'})">›</button></span></h3>${calendarGrid(m,ev)}<div style="margin-top:12px">${ev.filter(e=>e.date.startsWith(m)).sort((a,b)=>a.date.localeCompare(b.date)).map(e=>`<div class="row"><span><b>${esc(e.title)}</b><small>${fdl(e.date)} · ${e.cls==="All"?"Whole nursery":C(e.cls).name}</small></span><span class="st info">${e.type}</span></div>`).join("")||'<div class="list-empty">No events this month</div>'}</div></div>
   <div class="card"><h3>📣 ${T("Announcements")}${can?`<span class="x"><button class="btn sm navy" onclick="composeNotice()">+ New notice</button></span>`:""}</h3>${nw.map(n=>`<div class="row" style="align-items:flex-start"><span><b>${esc(n.title)}</b><small style="margin:3px 0">${esc(n.body)}</small><small>${fd(n.date)} · ${esc(n.by)} · ${n.to==="All"?"All parents":C(n.to).name}</small></span>${me.role!=="parent"?`<span class="st mute">${n.reads} read</span>`:""}</div>`).join("")}</div></div>`};
function composeNotice(){const opts=me.role==="teacher"?[[me.cls,C(me.cls).name+" parents"]]:[["All","All parents (62)"],...S.CLASSES.map(c=>[c.id,c.name+" parents"])];
  modal(mh("New notice","Posted in the parent app + WhatsApp notification")+`<div class="f"><label>Title</label><input id="nt" value="Early pick-up next Thursday"></div><div class="f"><label>Message</label><textarea id="nb">The nursery will close at 12:00 on Thursday 29 October for staff training.</textarea></div><div class="f"><label>Send to</label><select id="nto">${opts.map(o=>`<option value="${o[0]}">${o[1]}</option>`).join("")}</select></div><label style="display:flex;gap:8px;align-items:center;font-size:13px;margin-bottom:12px"><input type="checkbox" id="nev" checked> Also add to calendar</label><button class="btn full" onclick="sendNotice()">Publish & notify</button>`)}
function sendNotice(){const to=$("#nto").value;S.news.unshift({id:"N"+Date.now(),date:DEMO_TODAY,title:$("#nt").value,body:$("#nb").value,to,by:me.name,reads:0});if($("#nev").checked)S.events.push({date:"2026-10-29",title:$("#nt").value,cls:to,type:"Notice"});logComm("WhatsApp",to==="All"?"All parents (62)":C(to).name+" parents",$("#nt").value);closeModal();toast("Notice published · parents notified");go(view==="events"?"events":view)}

/* ---------- COMMS LOG ---------- */
V.comms=()=>`${ph("","Every WhatsApp, SMS, email and call to parents, logged automatically.",`<button class="btn sm navy" onclick="composeNotice()">📣 Broadcast</button>`)}<div class="kpis"><div class="kpi"><small>Messages this month</small><b>${412+S.commsLog.length}</b><em>WhatsApp 71% · SMS 18% · Email 11%</em></div><div class="kpi"><small>Delivered</small><b>99.2%</b></div><div class="kpi"><small>Read within 1 hour</small><b>86%</b></div></div>
  <div class="card"><div class="tbl"><table><thead><tr><th>When</th><th>Channel</th><th>To</th><th>Message</th></tr></thead><tbody>${S.commsLog.map(c=>`<tr><td class="num">${fd(c.t)} ${c.t.slice(11)}</td><td><span class="st ${c.ch==="WhatsApp"?"ok":c.ch==="SMS"?"info":"mute"}">${c.ch}</span></td><td>${esc(c.to)}</td><td>${esc(c.x)}</td></tr>`).join("")}</tbody></table></div></div>`;

/* ---------- ID CARDS ---------- */
V.idcards=(p)=>{const cls=(p&&p.cls)||"SF";return `<div class="toolbar noprint">${clsFilter("idc",cls,false)}<span class="sp"></span><button class="btn sm navy" onclick="printIds()">🖨 Print cards</button></div><div class="printable" id="idp"><div style="display:grid;grid-template-columns:repeat(auto-fill,minmax(250px,1fr));gap:14px">${classKids(cls).map(k=>`<div style="border-radius:16px;overflow:hidden;background:#fff;border:1px solid var(--line);break-inside:avoid"><div style="background:var(--navy);color:#fff;padding:10px 12px;display:flex;align-items:center;gap:8px"><svg style="width:28px;height:28px"><use href="#star"/></svg><b style="font-family:'Baloo 2';color:var(--gold);font-size:15px">Twinkle Star</b><span style="margin-inline-start:auto;font-size:10px;opacity:.8">STUDENT ID</span></div><div style="display:flex;gap:12px;padding:12px;align-items:center">${kidAv(k,"lg")}<div style="font-size:12px;line-height:1.5;flex:1"><b style="font-size:14px">${esc(k.name)}</b><br>${C(k.cls).name}<br>ID ${k.id} · Blood ${k.blood}<br>Emergency ${k.phone}</div><div style="transform:scale(.36);transform-origin:right center;width:66px;height:66px">${qrSvg(k.id)}</div></div><div style="background:${C(k.cls).color};height:6px"></div></div>`).join("")}</div></div>`};
function printIds(){const el=$("#idp");el.classList.add("printable");window.print()}

/* ---------- WEBSITE CMS ---------- */
V.cms=()=>{const s=S.site;let web=0;try{web=JSON.parse(localStorage.getItem("ts_enquiries")||"[]").length}catch(e){}
  return ph("","Update the public website without a developer. Changes go live instantly.",`<a class="btn sm light" href="index.html" target="_blank">Open website ↗</a>`)+`<div class="g g2"><div class="card"><h3>🌐 Homepage</h3><div class="f"><label>Announcement banner</label><input id="sb" value="${esc(s.banner)}"></div><label style="display:flex;gap:8px;align-items:center;font-size:13px;margin-bottom:12px"><input type="checkbox" id="ssb" ${s.showBanner?"checked":""}> Show banner on website</label><div class="f"><label>Hero headline</label><input id="sh" value="${esc(s.heroTitle)}"></div><div class="f"><label>Phone / WhatsApp</label><input id="sp" value="${esc(s.phone)}"></div><button class="btn full" onclick="publishSite()">Publish changes</button></div>
  <div class="stack"><div class="card"><h3>📊 Website this month</h3><div class="row"><span>Visitors</span><b>1,284</b></div><div class="row"><span>Visit bookings & enquiries</span><b>${18+web}</b></div><div class="row"><span>WhatsApp clicks</span><b>212</b></div><div class="row"><span>Portal sign-ins</span><b>2,960</b></div></div>
  <div class="card"><h3>🖼️ Gallery & pages</h3><div class="row"><span>Gallery photos</span><span class="st ok">9 published</span></div><div class="row"><span>Programmes</span><span class="st ok">4 published</span></div><div class="row"><span>FAQ</span><span class="st ok">6 questions</span></div><button class="btn sm light" style="margin-top:8px" onclick="toast('Demo: drag & drop photo upload')">+ Upload photos</button></div></div></div>`};
function publishSite(){Object.assign(S.site,{banner:$("#sb").value,showBanner:$("#ssb").checked,heroTitle:$("#sh").value,phone:$("#sp").value});try{localStorage.setItem("ts_site",JSON.stringify(S.site))}catch(e){}save();toast("Published · open the website to see it")}

/* ---------- INVENTORY ---------- */
V.inventory=()=>{const low=S.inventory.filter(i=>i.qty<i.min);return `<div class="kpis"><div class="kpi"><small>Items tracked</small><b>${S.inventory.length}</b></div><div class="kpi"><small>Below minimum</small><b>${low.length}</b><em class="${low.length?"w":"up"}">${low.length?"reorder now":"all good"}</em></div><div class="kpi"><small>Stock value</small><b>${f0(S.inventory.reduce((s,i)=>s+i.qty*i.cost,0))}<span> OMR</span></b></div></div>
  <div class="card"><div class="tbl"><table><thead><tr><th>Item</th><th>Category</th><th class="r">In stock</th><th class="r">Minimum</th><th>Status</th><th></th></tr></thead><tbody>${S.inventory.map((i,x)=>`<tr><td><b style="font-weight:600">${i.item}</b></td><td>${i.cat}</td><td class="r num">${i.qty} ${i.unit}</td><td class="r num">${i.min}</td><td>${i.qty<i.min?'<span class="st bad">Reorder</span>':i.qty<i.min*1.4?'<span class="st w">Low</span>':'<span class="st ok">OK</span>'}</td><td style="white-space:nowrap"><button class="btn sm light" onclick="S.inventory[${x}].qty=Math.max(0,S.inventory[${x}].qty-1);go('inventory')">− Use</button> <button class="btn sm" onclick="restock(${x})">+ Restock</button></td></tr>`).join("")}</tbody></table></div></div>`};
function restock(x){const i=S.inventory[x],q=i.min*2;i.qty+=q;S.expenses.unshift([DEMO_TODAY,"Supplies","Restock: "+i.item,+(q*i.cost).toFixed(3),"Card"]);toast(`Restocked ${q} ${i.unit} · expense of ${f3(q*i.cost)} OMR recorded`);go("inventory")}

/* ---------- TIMETABLE ---------- */
V.timetable=(p)=>{const cls=me.role==="teacher"?me.cls:me.role==="parent"?((p&&p.cls)||curKid().cls):((p&&p.cls)||"SF");const tt=S.timetable[cls];const sp={0:"Arabic story day",1:"Library & books",2:"Music with Ms. Amal",3:"Sports & movement",4:"Show & tell"};
  return `<div class="toolbar">${me.role==="parent"?`<div class="kidpick" style="margin:0">${parentKids().map(k=>`<button class="${k.cls===cls?"on":""}" onclick="go('timetable',{cls:'${k.cls}'})">${kidAv(k)}${k.first}</button>`).join("")}</div>`:me.role==="teacher"?"":clsFilter("ttc",cls,false)}</div>
  <div class="g g2"><div class="card"><h3>${C(cls).em} ${C(cls).name} · daily routine<span class="x">${C(cls).room}</span></h3><ul class="tl">${tt.map(t=>`<li><span class="t">${t[0]}</span><span>${t[1]}</span></li>`).join("")}</ul></div>
  <div class="card"><h3>Weekly specials</h3>${[0,1,2,3,4].map(d=>`<div class="row"><span><b>${["Sunday","Monday","Tuesday","Wednesday","Thursday"][d]}</b><small>${sp[d]}</small></span><span class="st info">10:00</span></div>`).join("")}${["admin","principal","exams"].includes(me.role)?`<button class="btn sm light" style="margin-top:10px" onclick="toast('Demo: timetable editor with drag & drop')">✎ Edit timetable</button>`:""}</div></div>`};

/* ---------- LESSON PLANS ---------- */
V.lessons=()=>{const list=S.lessons.filter(l=>me.role!=="teacher"||l.cls===me.cls);const canApprove=["exams","principal"].includes(me.role);
  return ph("","Weekly IPC-aligned plans, reviewed by the Head of Assessment.",me.role==="teacher"?`<button class="btn sm navy" onclick="newPlan()">+ New weekly plan</button>`:"")+`<div class="g g2">${list.map((l,i)=>`<div class="card"><h3>${C(l.cls).em} ${esc(l.theme)}<span class="x"><span class="st ${l.status==="Approved"?"ok":"w"}">${l.status}</span></span></h3><div class="hint" style="margin:-6px 0 10px">${C(l.cls).name} · ${l.week}</div><div style="display:flex;gap:6px;flex-wrap:wrap;margin-bottom:10px">${l.areas.map(a=>`<span class="st gold">${AREA_E[AREAS.indexOf(a)]||""} ${a}</span>`).join("")}</div><ul class="tl">${l.acts.map(a=>`<li><span class="e">•</span><span>${esc(a)}</span></li>`).join("")}</ul>${canApprove&&l.status!=="Approved"?`<button class="btn sm ok" style="margin-top:8px" onclick="S.lessons[${S.lessons.indexOf(l)}].status='Approved';toast('Plan approved · teacher notified');go('lessons')">Approve plan</button>`:""}</div>`).join("")}</div>`};
function newPlan(){modal(mh("New weekly plan")+`<div class="f"><label>Week</label><select id="pw"><option>Week 11 · 1–5 Nov</option></select></div><div class="f"><label>Theme</label><input id="pt" value="Healthy food"></div><div class="f"><label>Activities (one per line)</label><textarea id="pa">Fruit tasting\nSorting healthy & treat foods\nStory: 'The Very Busy Kitchen'\nArabic fruit names song</textarea></div><button class="btn full" onclick="S.lessons.unshift({cls:me.cls,week:$('#pw').value,theme:$('#pt').value,areas:['Science','Language','Physical'],acts:$('#pa').value.split('\\n').filter(Boolean),status:'Submitted'});closeModal();toast('Submitted for review');go('lessons')">Submit for review</button>`)}
